begin;
update public.public_profiles set pass_name_style='none' where pass_name_style in ('lab-blue-6-violet-haze','lab-blue-6-coral-cloud','lab-blue-6-emerald-veil','lab-blue-6-daybreak','lab-blue-6-moonlight','lab-blue-9-copper-orbit','lab-blue-9-green-comet','lab-blue-9-magenta-satellite','lab-blue-9-gravity');
update public.public_profiles set pass_border_style='none' where pass_border_style in ('lab-blue-6-violet-haze','lab-blue-6-coral-cloud','lab-blue-6-emerald-veil','lab-blue-6-daybreak','lab-blue-6-moonlight','lab-blue-9-copper-orbit','lab-blue-9-green-comet','lab-blue-9-magenta-satellite','lab-blue-9-gravity');
delete from public.box_inventory where kind in ('name','frame') and style in ('lab-blue-6-violet-haze','lab-blue-6-coral-cloud','lab-blue-6-emerald-veil','lab-blue-6-daybreak','lab-blue-6-moonlight','lab-blue-9-copper-orbit','lab-blue-9-green-comet','lab-blue-9-magenta-satellite','lab-blue-9-gravity');
delete from public.box_style_catalog c where style in ('lab-blue-6-violet-haze','lab-blue-6-coral-cloud','lab-blue-6-emerald-veil','lab-blue-6-daybreak','lab-blue-6-moonlight','lab-blue-9-copper-orbit','lab-blue-9-green-comet','lab-blue-9-magenta-satellite','lab-blue-9-gravity') and not exists(select 1 from public.box_openings o where o.style=c.style);
alter table public.public_profiles add constraint retired_oct9_name_styles check(pass_name_style not in ('lab-blue-6-violet-haze','lab-blue-6-coral-cloud','lab-blue-6-emerald-veil','lab-blue-6-daybreak','lab-blue-6-moonlight','lab-blue-9-copper-orbit','lab-blue-9-green-comet','lab-blue-9-magenta-satellite','lab-blue-9-gravity'));
alter table public.public_profiles add constraint retired_oct9_frame_styles check(pass_border_style not in ('lab-blue-6-violet-haze','lab-blue-6-coral-cloud','lab-blue-6-emerald-veil','lab-blue-6-daybreak','lab-blue-6-moonlight','lab-blue-9-copper-orbit','lab-blue-9-green-comet','lab-blue-9-magenta-satellite','lab-blue-9-gravity'));
do $$ declare definition text; style text; begin
 definition:=pg_get_functiondef('public.box_style_allowed(uuid,text,text)'::regprocedure);
 foreach style in array array['lab-blue-6-violet-haze','lab-blue-6-coral-cloud','lab-blue-6-emerald-veil','lab-blue-6-daybreak','lab-blue-6-moonlight','lab-blue-9-copper-orbit','lab-blue-9-green-comet','lab-blue-9-magenta-satellite','lab-blue-9-gravity'] loop
  definition:=replace(definition,quote_literal(style)||',','');
 end loop;
 execute definition;
end $$;
notify pgrst,'reload schema';
commit;
select (select count(*) from public.public_profiles where pass_name_style in ('lab-blue-6-violet-haze','lab-blue-6-coral-cloud','lab-blue-6-emerald-veil','lab-blue-6-daybreak','lab-blue-6-moonlight','lab-blue-9-copper-orbit','lab-blue-9-green-comet','lab-blue-9-magenta-satellite','lab-blue-9-gravity') or pass_border_style in ('lab-blue-6-violet-haze','lab-blue-6-coral-cloud','lab-blue-6-emerald-veil','lab-blue-6-daybreak','lab-blue-6-moonlight','lab-blue-9-copper-orbit','lab-blue-9-green-comet','lab-blue-9-magenta-satellite','lab-blue-9-gravity')) equipped,(select count(*) from public.box_inventory where style in ('lab-blue-6-violet-haze','lab-blue-6-coral-cloud','lab-blue-6-emerald-veil','lab-blue-6-daybreak','lab-blue-6-moonlight','lab-blue-9-copper-orbit','lab-blue-9-green-comet','lab-blue-9-magenta-satellite','lab-blue-9-gravity')) inventory_items,(select count(*) from public.box_style_catalog where style in ('lab-blue-6-violet-haze','lab-blue-6-coral-cloud','lab-blue-6-emerald-veil','lab-blue-6-daybreak','lab-blue-6-moonlight','lab-blue-9-copper-orbit','lab-blue-9-green-comet','lab-blue-9-magenta-satellite','lab-blue-9-gravity')) catalog_items;
